-- READ ONLY. Compare old_ledger_hash to saved preflight full_ledger_hash.
SELECT jsonb_build_object('old_ledger_hash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(m)ORDER BY version),'[]')::text)FROM supabase_migrations.schema_migrations m WHERE version<>'20261020150000'),'new_ledger',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',cardinality(statements),'migration_md5',md5(statements[1])))FROM supabase_migrations.schema_migrations WHERE version='20261020150000'),'urgent_rpc_md5',md5(pg_get_functiondef('public.get_organization_students_page(uuid,integer,integer,text,uuid,text,text,text,text)'::regprocedure)),'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',p.proowner,'acl',p.proacl,'security_definer',p.prosecdef,'configuration',p.proconfig,'body_md5',md5(p.prosrc))ORDER BY p.oid::regprocedure::text)FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'AND(p.proname LIKE 'uc_custom_journal_%'OR p.proname IN('read_custom_journals','apply_custom_journal_action'))),'erasure',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'oid',p.oid,'owner',p.proowner,'acl',p.proacl,'definition_md5',md5(pg_get_functiondef(p.oid)))ORDER BY p.oid::regprocedure::text)FROM pg_proc p WHERE p.oid IN('public.account_deletion_personal_row_counts(uuid)'::regprocedure,'public.account_deletion_snapshot(uuid)'::regprocedure,'public.account_deletion_erase_data(uuid,text)'::regprocedure)))AS uc015_postcheck;
